interface ProductsUpdateEvent extends CustomEvent {
  detail: {
    sections: Record<string, string>;
  };
}

class SortForm extends HTMLElement {
  private unsubscribe: (() => void) | undefined;

  constructor() {
    super();
  }

  connectedCallback(): void {
    const sectionId = this.getAttribute("data-section-id");

    if (!sectionId) {
      return;
    }

    this.setupSortHandler();
  }

  disconnectedCallback(): void {
    this.unsubscribe?.();
  }

  private setupSortHandler(): void {
    const sortSelect = this.querySelector<HTMLSelectElement>("select");

    if (!sortSelect) {
      return;
    }

    sortSelect.addEventListener("change", async (event) => {
      const select = event.target as HTMLSelectElement;
      const sortValue = select.value;

      if (!sortValue) return;

      const sectionId = this.getAttribute("data-section-id");
      if (!sectionId) return;

      const searchParams = [
        this.querySelector("form"),
        document.querySelector("uwp-filter-form form"),
      ]
        .filter(Boolean)
        .map((form) => {
          // @ts-expect-error - TS doesn't know that filter(Boolean) removes nulls
          return new URLSearchParams(new FormData(form)).toString();
        })
        .filter(Boolean)
        .join("&");

      try {
        const sections = await fetch(
          `${location.pathname}?sections=${sectionId}&${searchParams}`,
        ).then((r) => r.json());

        document.dispatchEvent(
          new CustomEvent("products:update", {
            detail: { sections },
          }) as ProductsUpdateEvent,
        );

        history.pushState(
          { searchParams },
          "",
          `${window.location.pathname}${
            searchParams.includes("?") || !searchParams
              ? searchParams
              : "?".concat(searchParams)
          }`,
        );
      } catch (error) {
        console.error("Failed to update sort:", error);
      }
    });
  }
}

if (!customElements.get("uwp-sort-form")) {
  customElements.define("uwp-sort-form", SortForm);
}

export default SortForm;
